import math

def affected(r, h) -> bool:
    # NaN never compares equal, so any NaN input counts as a difference
    if math.isnan(r) or math.isnan(h):
        return True
    # r == 0: mutant raises ZeroDivisionError, original does not
    if r == 0:
        return True
    # infinite h: results agree only when r is finite and r <= 2*pi
    if math.isinf(h):
        return not (math.isfinite(r) and r <= 2 * math.pi)
    # finite nonzero h: with h == 0 the results agree when r is finite
    if h == 0:
        return not math.isfinite(r)
    # otherwise the floor-division changes the value
    return True
